mapper.select:
SELECT ranked_orders.page
FROM (
    SELECT
        id,
        FLOOR((ROW_NUMBER() OVER (ORDER BY pickup_at, created_at, id) - 1) / #{size}) + 1 AS page
    FROM orders
    WHERE status = #{status}
) AS ranked_orders
WHERE ranked_orders.id = #{orderId}

SELECT EXISTS (
    SELECT 1
    FROM orders
    WHERE id = #{orderId}
      AND member_id = #{memberId}
)

mapper.update:
UPDATE order_items
SET stock_deducted_at = #{deductedAt}
WHERE id = #{orderItemId}
  AND stock_deducted_at IS NULL
  AND stock_restored_at IS NULL

UPDATE order_items
SET stock_restored_at = #{restoredAt}
WHERE id = #{orderItemId}
  AND stock_deducted_at IS NOT NULL
  AND stock_restored_at IS NULL
